-- ============================================================================
-- godbsync CI 种子数据：PostgreSQL 源端（13+，CI 用 16）
--
-- 与 mysql.sql / sqlserver.sql / oracle.sql 保持一致：同名、同列序、同语义类型。
-- 标识符全大写（理由见 mysql.sql 顶部说明）。PostgreSQL 会把未加引号的大写标识符
-- 折叠为小写 —— 这是 PG 的默认行为，godbsync 的 pgType/PrimaryKey 已按 LOWER 比较
-- 做了兼容（见 internal/postgresql/postgresql.go 注释），故这里保持与其他方言一致的裸大写写法。
-- ============================================================================

DROP TABLE IF EXISTS T_ANCHOR;
DROP TABLE IF EXISTS T_TYPES;
DROP TABLE IF EXISTS T_RESERVED;
DROP TABLE IF EXISTS T_NOPK;
DROP TABLE IF EXISTS T_EMPTY;

-- ---------------------------------------------------------------------------
-- T_ANCHOR：1200 行，单列主键 + 单调时间列（有序断点 / 增量水位）
-- ---------------------------------------------------------------------------
CREATE TABLE T_ANCHOR (
  ID BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  NAME VARCHAR(64) NOT NULL,
  AMOUNT NUMERIC(18,4),
  UPDATED_AT TIMESTAMP(6) NOT NULL
);
COMMENT ON TABLE T_ANCHOR IS '断点续传与水位探针';
COMMENT ON COLUMN T_ANCHOR.NAME IS '业务名称（含中文，验证字符集透传）';
COMMENT ON COLUMN T_ANCHOR.UPDATED_AT IS '增量水位列，按行号单调递增';

INSERT INTO T_ANCHOR (NAME, AMOUNT, UPDATED_AT)
SELECT 'row-' || lpad(i::text, 5, '0') || '-中文',
       round((i * 1.2345)::numeric, 4),
       TIMESTAMP '2024-01-01 00:00:00' + (i || ' second')::interval
FROM generate_series(1, 1200) AS i;

-- ---------------------------------------------------------------------------
-- T_TYPES：类型边界探针（精度 / 长文本 / 微秒 / 二进制 / 全 NULL 行）
-- ---------------------------------------------------------------------------
CREATE TABLE T_TYPES (
  ID INTEGER NOT NULL PRIMARY KEY,
  C_DEC NUMERIC(38,10),
  C_BIG BIGINT,
  C_FLOAT DOUBLE PRECISION,
  C_VC VARCHAR(255),
  C_TXT TEXT,
  C_DATE DATE,
  C_TS TIMESTAMP(6),
  C_BOOL BOOLEAN,
  C_BIN BYTEA
);
COMMENT ON TABLE T_TYPES IS '类型映射边界探针';

INSERT INTO T_TYPES (ID, C_DEC, C_BIG, C_FLOAT, C_VC, C_TXT, C_DATE, C_TS, C_BOOL, C_BIN) VALUES
(1, 1234567890123456789012345678.0123456789, 9223372036854775807, 3.141592653589793,
 '普通中文与 ASCII 混排 abcXYZ', repeat('长文本测试', 1500),
 DATE '2024-03-05', TIMESTAMP '2024-03-05 12:34:56.123456', true, decode('000102030405060708090A0B0C0D0E0F', 'hex')),
(2, -1234567890123456789012345678.0123456789, -9223372036854775808, -2.718281828459045,
 '负数与极小值', '短文本',
 DATE '1970-01-02', TIMESTAMP '1970-01-02 00:00:00.000001', false, decode('FFEEDDCCBBAA99887766554433221100', 'hex')),
(3, 0.0000000001, 0, 0,
 '', '',
 DATE '2024-12-31', TIMESTAMP '2024-12-31 23:59:59.999999', false, decode('00', 'hex')),
(4, 9999999999999999999999999999.9999999999, 1, 1.5,
 '特殊字符: 单引号 '' 反斜杠 \ 制表 ' || chr(9) || ' 换行 ' || chr(10) || ' 表情 😀🎉 结束',
 '含 emoji 的文本 😀', DATE '2000-02-29', TIMESTAMP '2000-02-29 00:00:00.000000', true, decode('DEADBEEF', 'hex')),
(5, -0.0000000001, -1, -1.5,
 '边界长度: 这是一个用于验证 255 字符上限的填充值', repeat('x', 100),
 DATE '2038-01-18', TIMESTAMP '2038-01-19 03:14:07.000000', true, NULL),
(6, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

-- ---------------------------------------------------------------------------
-- T_RESERVED：保留字列名（ORDER / GROUP / DESC / KEY 必须加双引号）
-- ---------------------------------------------------------------------------
CREATE TABLE T_RESERVED (
  ID INTEGER NOT NULL PRIMARY KEY,
  "ORDER" INTEGER,
  "GROUP" VARCHAR(32),
  "DESC" VARCHAR(64),
  "KEY" VARCHAR(32)
);
COMMENT ON TABLE T_RESERVED IS '保留字列名探针';

INSERT INTO T_RESERVED (ID, "ORDER", "GROUP", "DESC", "KEY") VALUES
(1, 100, 'g-alpha', '第一行描述', 'k1'),
(2, -100, 'g-beta', '第二行描述', 'k2'),
(3, 0, '', '第三行描述', 'k3');

-- ---------------------------------------------------------------------------
-- T_NOPK：无主键表（PG 源退化为无序全量）
-- ---------------------------------------------------------------------------
CREATE TABLE T_NOPK (
  K1 INTEGER,
  K2 VARCHAR(32),
  K3 NUMERIC(10,2)
);
COMMENT ON TABLE T_NOPK IS '无主键表';

INSERT INTO T_NOPK (K1, K2, K3)
SELECT i, 'np-' || i, round((i * 1.25)::numeric, 2)
FROM generate_series(1, 50) AS i;

-- ---------------------------------------------------------------------------
-- T_EMPTY：0 行表
-- ---------------------------------------------------------------------------
CREATE TABLE T_EMPTY (
  ID INTEGER NOT NULL PRIMARY KEY,
  V VARCHAR(10)
);
COMMENT ON TABLE T_EMPTY IS '空表';

-- ---------------------------------------------------------------------------
-- 自检：各表预期行数
-- ---------------------------------------------------------------------------
SELECT 'T_ANCHOR' AS tab, count(*) AS rows_ FROM T_ANCHOR
UNION ALL SELECT 'T_TYPES', count(*) FROM T_TYPES
UNION ALL SELECT 'T_RESERVED', count(*) FROM T_RESERVED
UNION ALL SELECT 'T_NOPK', count(*) FROM T_NOPK
UNION ALL SELECT 'T_EMPTY', count(*) FROM T_EMPTY;
